<script lang="ts">
	import { api, type RecordValue } from '$lib/api';
	import PairedMetricPlot from '$lib/PairedMetricPlot.svelte';
	export let summary: RecordValue | null = null;
	export let artifactId = '';
	const object = (value: unknown): RecordValue => value && typeof value === 'object' ? value as RecordValue : {};
	const entries = (value: RecordValue) => Object.entries(value).filter(([, item]) => typeof item === 'number' && Number.isFinite(item));
	let history: RecordValue[] = []; let selectedMetric = ''; let loading = false; let error = ''; let loadedArtifactId = ''; let request = 0;
	$: outputs = object(summary?.outputs); $: latest = object(summary?.latest_metrics);
	$: metricKeys = [...new Set([...(Array.isArray(summary?.metric_keys) ? summary!.metric_keys.map(String) : []), ...history.flatMap((row) => Object.keys(row).filter((key) => typeof row[key] === 'number' && !['epoch','step'].includes(key)))])].filter((key) => !['epoch','step','phase_id'].includes(key));
	$: if (!selectedMetric && metricKeys.length) selectedMetric = metricKeys.find((key) => ['loss','simclr_loss','cosine_similarity','encoder_representation_std'].includes(key)) ?? metricKeys[0];
	async function load() { const id = artifactId; const token = ++request; history = []; selectedMetric = ''; if (!id || summary?.history_available === false) { loading = false; return; } loading = true; error = ''; try { const result = await api.artifactHistory(id, 2000, 'self_supervised'); if (token === request) history = Array.isArray(result.rows) ? result.rows as RecordValue[] : []; } catch (cause) { if (token === request) error = cause instanceof Error ? cause.message : 'Could not load SSL history.'; } finally { if (token === request) loading = false; } }
	$: if (artifactId !== loadedArtifactId) { loadedArtifactId = artifactId; void load(); }
</script>

{#if summary?.enabled || Object.keys(summary ?? {}).length}<section class="ssl-results"><div class="panel-head"><div><p class="eyebrow">SELF-SUPERVISED LEARNING</p><h3>{String(summary?.method ?? 'Representation pretraining').replaceAll('_', ' ')}</h3><p>Planned {summary?.planned_epochs ?? '—'} epochs · completed {summary?.completed_epochs ?? '—'}.</p></div></div>{#if error}<p class="inline-error" role="alert">{error}</p>{/if}<div class="ssl-facts"><div><span>Status</span><strong>{summary?.enabled === false ? 'Not enabled' : Number(summary?.completed_epochs) >= Number(summary?.planned_epochs) && Number(summary?.planned_epochs) > 0 ? 'Complete' : Number(summary?.completed_epochs) > 0 ? 'Partial history' : 'No retained history'}</strong></div>{#each entries(latest) as [key,value]}<div><span>{key.replaceAll('_',' ')}</span><strong>{Number(value).toLocaleString(undefined,{maximumFractionDigits:4})}</strong></div>{/each}</div>{#if Object.keys(outputs).length}<details><summary>Saved SSL outputs</summary>{#if Array.isArray(summary?.files) && summary.files.length}<ul>{#each summary.files as file}<li><code>{String(object(file).path)}</code> · {String(object(file).kind).replaceAll('_', ' ')}</li>{/each}</ul>{:else}<p>{outputs.metrics ? 'SSL metrics are retained.' : 'No SSL metrics file is retained.'} {outputs.weights ? 'Pretrained weights are retained.' : 'No separate pretrained weights are retained.'}</p>{/if}</details>{/if}{#if metricKeys.length}<label class="ssl-picker">Metric<select bind:value={selectedMetric}>{#each metricKeys as metric}<option value={metric}>{metric.replaceAll('_',' ')}</option>{/each}</select></label>{#if loading}<p class="empty">Loading SSL history…</p>{:else if history.length}<PairedMetricPlot points={history} metric={selectedMetric} title={`SSL ${selectedMetric.replaceAll('_',' ')}`} mode="epoch" validationExpected={false} />{:else}<p class="empty">No SSL epoch history was retained.</p>{/if}{/if}{#if summary?.health}<details open><summary>Exported embedding health · {String(object(summary.health).status)}</summary><pre>{JSON.stringify(summary.health,null,2)}</pre></details>{/if}<details><summary>Saved SSL settings and provenance</summary><pre>{JSON.stringify(summary,null,2)}</pre></details></section>{/if}

